(function tick(t) {
    const el = t - t0;
    ctx.clearRect(0, 0, c.width, c.height);
    for (const p of ps) {
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.35;
      p.r += p.vr;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.r);
      ctx.fillStyle = p.col;
      ctx.globalAlpha = Math.max(0, 1 - el / 1300);
      ctx.fillRect(-p.s / 2, -p.s / 2, p.s, p.s * 0.6);
      ctx.restore();
    }
    if (el < 1300) requestAnimationFrame(tick);
    else c.remove();
  })
